// types.ts

export enum Screen {
  Login,
  DriverConfirmation,
  Home,
  TripSelection,
  RouteSelection, // New Screen
  ActiveTrip,
  TripSummary,
  GateAttendance,
  Profile,
  History,
  TripReport,
  Settings,
}

export type GpsStatus = 'active' | 'inactive' | 'error';
export type Coordinates = { lat: number; lon: number };

export enum StudentStatus {
  NotBoarded = 'Not Boarded',
  Boarded = 'Boarded',
  Absent = 'Absent',
  Alighted = 'Alighted',
  InSchool = 'In School',
  NotArrived = 'Not Arrived',
  LeftSchool = 'Left School',
}

export interface Student {
  id: string;
  name: string;
  admissionNumber: string;
  grade: string;
  status: StudentStatus;
  imgUrl: string;
  alert?: string; // For highlighting students with issues
  lastUpdateTime?: Date;
}

export interface Guardian {
  id: string;
  name: string;
  phone: string;
  idNumber: string;
  relationship: string;
  imgUrl: string;
  authorizedStudentId: string;
}

export type TripType = 'Morning' | 'Afternoon';

export interface Route {
    id: string;
    name: string;
    zone: string;
    studentCount: number;
    estimatedDuration: string;
}

export interface Trip {
  type: TripType;
  route: Route; // Updated to use the full Route object
  startTime: Date;
  endTime?: Date;
  students: Student[];
  issues: Issue[];
}

export enum IssueType {
    Traffic = 'Traffic delay',
    Vehicle = 'Vehicle issue',
    Weather = 'Weather issue',
    Safety = 'Safety incident',
}

export interface Issue {
    type: IssueType;
    note: string;
    timestamp: Date;
}

export type ToastType = 'success' | 'error' | 'info';

export interface VerificationHistoryItem {
  id: string;
  guardianName: string;
  studentName: string;
  timestamp: Date;
  verifiedBy: string;
  guardianImgUrl: string;
  studentImgUrl: string;
  // Added for more detail
  studentGrade: string;
  guardianPhone: string;
  guardianIdNumber: string;
  guardianRelationship: string;
}

export interface TripHistoryItem extends Trip {
  id: string;
}

export interface DataUsageItem {
  date: string;
  usage: number; // in MB
}

