const DateRangePickerModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    onApply: (start: Date, end: Date) => void;
    initialRange: { start: Date | null, end: Date | null };
}> = ({ isOpen, onClose, onApply, initialRange }) => {
    const toInputFormat = (date: Date | null) => date ? date.toISOString().split('T')[0] : '';

    const [start, setStart] = useState(toInputFormat(initialRange.start));
    const [end, setEnd] = useState(toInputFormat(initialRange.end));
    const [error, setError] = useState('');

    useEffect(() => {
        if (isOpen) {
            setStart(toInputFormat(initialRange.start));
            setEnd(toInputFormat(initialRange.end));
            setError('');
        }
    }, [isOpen, initialRange]);

    const handleApply = () => {
        setError('');
        if (start && end) {
            const startDate = new Date(start + 'T00:00:00');
            const endDate = new Date(end + 'T00:00:00');
            if (endDate < startDate) {
                setError('End date cannot be before start date.');
                return;
            }
            onApply(startDate, endDate);
        }
    };

    return (
        <Modal isOpen={isOpen} onClose={onClose} title="Select Date Range">
            <div className="space-y-4">
                <div>
                    <label htmlFor="startDate" className="block text-sm font-medium text-gray-700">Start Date</label>
                    <input 
                        type="date" 
                        id="startDate" 
                        value={start} 
                        onChange={e => setStart(e.target.value)} 
                        className="mt-1 block w-full rounded-xl border-gray-200 shadow-sm focus:border-[#E70D8D] focus:ring-[#E70D8D] sm:text-sm p-3 bg-gray-50"
                    />
                </div>
                <div>
                    <label htmlFor="endDate" className="block text-sm font-medium text-gray-700">End Date</label>
                    <input 
                        type="date" 
                        id="endDate" 
                        value={end} 
                        onChange={e => setEnd(e.target.value)} 
                        className="mt-1 block w-full rounded-xl border-gray-200 shadow-sm focus:border-[#E70D8D] focus:ring-[#E70D8D] sm:text-sm p-3 bg-gray-50"
                    />
                </div>
                {error && <p className="text-red-500 text-sm">{error}</p>}
                <button onClick={handleApply} className="w-full bg-[#E70D8D] text-white font-bold p-3 rounded-xl mt-4 hover:opacity-90">Apply Filter</button>
            </div>
        </Modal>
    );
};

const HistoryScreen: React.FC<{
    onBack: () => void;
    initialTab: 'trip' | 'verification';
    onSelectTrip: (trip: TripHistoryItem) => void;
    onSelectVerification: (verification: VerificationHistoryItem) => void;
    customDateRange: { start: Date | null, end: Date | null };
    onOpenDateRangePicker: () => void;
    setCustomDateRange: (range: { start: Date | null, end: Date | null }) => void;
}> = ({ onBack, initialTab, onSelectTrip, onSelectVerification, customDateRange, onOpenDateRangePicker, setCustomDateRange }) => {
    const [activeTab, setActiveTab] = useState(initialTab);

    const formatDate = (date: Date) => date.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });

    const filterByDate = (itemDate: Date) => {
        if (!customDateRange.start || !customDateRange.end) return true;
        return itemDate >= customDateRange.start && itemDate <= customDateRange.end;
    };

    const trips = MOCK_TRIP_HISTORY.filter(t => filterByDate(t.startTime));
    const verifications = MOCK_VERIFICATION_HISTORY.filter(v => filterByDate(v.timestamp));

    const clearFilters = () => setCustomDateRange({ start: null, end: null });
    const hasFilter = customDateRange.start && customDateRange.end;

    return (
        <div className="flex flex-col h-full bg-gray-50">
            <Header title="History" onBack={onBack} />
            <div className="p-4 bg-white border-b border-gray-100">
                <div className="flex bg-gray-100 rounded-xl p-1 mb-4">
                    <button 
                        className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'trip' ? 'bg-[#E70D8D] text-white shadow-sm' : 'text-gray-500'}`} 
                        onClick={() => setActiveTab('trip')}
                    >
                        Trips
                    </button>
                    <button 
                        className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'verification' ? 'bg-[#E70D8D] text-white shadow-sm' : 'text-gray-500'}`} 
                        onClick={() => setActiveTab('verification')}
                    >
                        Verifications
                    </button>
                </div>
                <div className="flex justify-between items-center">
                    <button onClick={onOpenDateRangePicker} className="flex items-center gap-2 text-sm font-medium text-gray-600 bg-gray-50 px-3 py-2 rounded-lg hover:bg-gray-100">
                        <Icon name="clock" className="w-4 h-4"/>
                        {hasFilter ? `${formatDate(customDateRange.start!)} - ${formatDate(customDateRange.end!)}` : 'Filter by Date'}
                    </button>
                    {hasFilter && <button onClick={clearFilters} className="text-xs text-red-500 font-bold uppercase hover:underline">Clear</button>}
                </div>
            </div>

            <div className="flex-grow overflow-y-auto p-4">
                {activeTab === 'trip' ? (
                    <div className="space-y-3">
                        {trips.length > 0 ? trips.map(trip => (
                            <div key={trip.id} onClick={() => onSelectTrip(trip)} className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex items-center gap-4 cursor-pointer hover:border-pink-200 transition-colors">
                                <div className="bg-pink-50 p-3 rounded-full">
                                    <Icon name={trip.type === 'Morning' ? 'sun' : 'moon'} className="w-5 h-5 text-[#E70D8D]"/>
                                </div>
                                <div className="flex-grow">
                                    <p className="font-bold text-gray-800">{trip.type} Trip</p>
                                    <p className="text-xs text-gray-500">{formatDate(trip.startTime)} • {trip.startTime.toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'})}</p>
                                </div>
                                <div className="text-right">
                                     <p className="text-xs font-bold text-gray-400 uppercase mb-1">Students</p>
                                     <p className="font-bold text-[#303690]">{trip.students.length}</p>
                                </div>
                                <Icon name="arrowRight" className="w-4 h-4 text-gray-300"/>
                            </div>
                        )) : <EmptyState message="No trips found." />}
                    </div>
                ) : (
                    <div className="space-y-3">
                         {verifications.length > 0 ? verifications.map(v => (
                            <div key={v.id} onClick={() => onSelectVerification(v)} className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex items-center gap-4 cursor-pointer hover:border-pink-200 transition-colors">
