const App: React.FC = () => {
    const [screen, setScreen] = useState<Screen>(Screen.Login);
    const [isLoadingScreen, setIsLoadingScreen] = useState(false);
    const [activeTrip, setActiveTrip] = useState<Trip | null>(null);
    const [selectedTripType, setSelectedTripType] = useState<TripType | null>(null);
    const [toast, setToast] = useState<{ message: string; type: ToastType } | null>(null);
    const [modal, setModal] = useState<'delay' | 'otp' | 'version' | 'logout' | 'dateRange' | 'verificationDetails' | 'dataHistory' | 'map' | null>(null);
    const [historyType, setHistoryType] = useState<'trip' | 'verification'>('trip');
    const [selectedTripReport, setSelectedTripReport] = useState<TripHistoryItem | null>(null);
    const [selectedVerification, setSelectedVerification] = useState<VerificationHistoryItem | null>(null);
    const [customDateRange, setCustomDateRange] = useState<{ start: Date | null, end: Date | null }>({ start: null, end: null });
    const [gpsStatus, setGpsStatus] = useState<GpsStatus>('inactive');
    const [currentLocation, setCurrentLocation] = useState<Coordinates | null>(null);
    const [dataUsage, setDataUsage] = useState(12.4);
    const [dataUsageHistory, setDataUsageHistory] = useState(MOCK_DATA_USAGE_HISTORY);
    const [settings, setSettings] = useState({ notifications: true, offlineMode: false });
    const [isOnline, setIsOnline] = useState(navigator.onLine);
    const [batteryStatus, setBatteryStatus] = useState<{ level: number, charging: boolean } | null>(null);

    useEffect(() => {
        let watchId: number;
        if (screen === Screen.ActiveTrip) {
            setGpsStatus('active');
            watchId = navigator.geolocation.watchPosition(
                (position) => {
                    setCurrentLocation({ lat: position.coords.latitude, lon: position.coords.longitude });
                    if (gpsStatus !== 'active') setGpsStatus('active');
                },
                (error) => setGpsStatus('error'),
                { enableHighAccuracy: true }
            );
        }
        return () => { if (watchId) navigator.geolocation.clearWatch(watchId); setGpsStatus('inactive'); setCurrentLocation(null); };
    }, [screen]);

    useEffect(() => {
        const interval = setInterval(() => setDataUsage(prev => +(prev + 0.01).toFixed(2)), 5000);
        return () => clearInterval(interval);
    }, []);

    const showToast = (message: string, type: ToastType = 'success') => setToast({ message, type });

    useEffect(() => {
        const handleOnline = () => { setIsOnline(true); showToast('Back online.', 'success'); };
        const handleOffline = () => { setIsOnline(false); showToast('Connection lost.', 'error'); };
        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);
        return () => { window.removeEventListener('online', handleOnline); window.removeEventListener('offline', handleOffline); };
    }, []);

    const navigate = (newScreen: Screen) => {
        setIsLoadingScreen(true);
        setTimeout(() => {
            setScreen(newScreen);
            setIsLoadingScreen(false);
        }, 800);
    };

    const startTrip = (route: Route) => {
        if (!selectedTripType) return;
        const students = MOCK_STUDENTS.map(s => ({...s, status: StudentStatus.NotBoarded}));
        setActiveTrip({ type: selectedTripType, route, startTime: new Date(), students, issues: [] });
        navigate(Screen.ActiveTrip);
    };

    const updateStudentStatus = (studentId: string, newStatus: StudentStatus) => {
        if (activeTrip) {
            setActiveTrip(prev => {
                if (!prev) return null;
                return { ...prev, students: prev.students.map(s => s.id === studentId ? { ...s, status: newStatus, lastUpdateTime: new Date() } : s) };
            });
        }
    };

    const renderScreen = () => {
        if (isLoadingScreen) return <div className="h-full w-full flex items-center justify-center bg-white"><Spinner size={40} className="text-[#303690]"/></div>;

        switch (screen) {
            case Screen.Login: return <LoginScreen onLogin={() => navigate(Screen.DriverConfirmation)} version={APP_VERSION} onVersionClick={() => setModal('version')} />;
            case Screen.DriverConfirmation: return <DriverConfirmationScreen onConfirm={() => navigate(Screen.Home)} version={APP_VERSION} onVersionClick={() => setModal('version')} />;
            case Screen.Home: return <HomeScreen navigate={navigate} setHistoryType={setHistoryType} onVersionClick={() => setModal('version')} />;
            case Screen.TripSelection: return <TripSelectionScreen onSelectTripType={(type) => { setSelectedTripType(type); navigate(Screen.RouteSelection); }} onBack={() => navigate(Screen.Home)} />;
            case Screen.RouteSelection: return <RouteSelectionScreen onSelectRoute={startTrip} onBack={() => navigate(Screen.TripSelection)} />;
            case Screen.ActiveTrip: return activeTrip && <ActiveTripScreen trip={activeTrip} onEndTrip={() => navigate(Screen.TripSummary)} onUpdateStudent={updateStudentStatus} onReportIssue={() => setModal('delay')} showToast={showToast} gpsStatus={gpsStatus} onGpsClick={() => setModal('map')} setActiveTrip={setActiveTrip} />;
            case Screen.TripSummary: return activeTrip && <TripSummaryScreen trip={activeTrip} onDone={() => { setActiveTrip(null); navigate(Screen.Home); }} onBack={() => navigate(Screen.ActiveTrip)} />;
            case Screen.GateAttendance: return <GateAttendanceScreen onBack={() => navigate(Screen.Home)} onGuardianVerify={() => setModal('otp')} showToast={showToast}/>;
            case Screen.Profile: return <ProfileScreen onBack={() => navigate(Screen.Home)} onLogoutClick={() => setModal('logout')} onSettingsClick={() => navigate(Screen.Settings)} />;
            case Screen.Settings: return <SettingsScreen onBack={() => navigate(Screen.Profile)} settings={settings} onSettingChange={(k, v) => setSettings(s => ({...s, [k]: v}))} dataUsage={dataUsage} onOpenDataHistory={() => setModal('dataHistory')} />;
            case Screen.History: return <HistoryScreen onBack={() => navigate(Screen.Home)} initialTab={historyType} onSelectTrip={(t) => { setSelectedTripReport(t); navigate(Screen.TripReport); }} onSelectVerification={(v) => { setSelectedVerification(v); setModal('verificationDetails'); }} customDateRange={customDateRange} onOpenDateRangePicker={() => setModal('dateRange')} setCustomDateRange={setCustomDateRange} />;
            case Screen.TripReport: return selectedTripReport && <TripReportScreen trip={selectedTripReport} onClose={() => navigate(Screen.History)} />;
            default: return <LoginScreen onLogin={() => navigate(Screen.Home)} version={APP_VERSION} onVersionClick={() => setModal('version')} />;
        }
    };

    return (
        <div className="h-full w-full bg-gray-50 font-sans flex flex-col relative pt-8 overflow-hidden">
            {!isOnline && <SystemStatusBanner message="No Connection" icon="wifiOff" className="bg-red-600" />}
            {renderScreen()}
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

            <DelayReportModal isOpen={modal === 'delay'} onClose={() => setModal(null)} onReport={(i) => { setActiveTrip(prev => prev ? {...prev, issues: [...prev.issues, i]} : null); setModal(null); showToast('Issue reported'); }} />
            <GuardianOtpModal isOpen={modal === 'otp'} onClose={() => setModal(null)} onSuccess={(g, s) => showToast(`Verified: ${s} released to ${g}`)} />
            <VersionInfoModal isOpen={modal === 'version'} onClose={() => setModal(null)} />
            <LogoutConfirmationModal isOpen={modal === 'logout'} onClose={() => setModal(null)} onConfirm={() => { setModal(null); setScreen(Screen.Login); }} />
            <DateRangePickerModal isOpen={modal === 'dateRange'} onClose={() => setModal(null)} onApply={(s, e) => { setCustomDateRange({ start: s, end: e }); setModal(null); }} initialRange={customDateRange} />
            <VerificationDetailsModal isOpen={modal === 'verificationDetails'} onClose={() => setModal(null)} verification={selectedVerification} />
            <DataUsageHistoryModal isOpen={modal === 'dataHistory'} onClose={() => setModal(null)} history={dataUsageHistory} onReset={() => { setDataUsage(0); setModal(null); }} />
            <MapModal isOpen={modal === 'map'} onClose={() => setModal(null)} location={currentLocation} />
        </div>
    );
};

