const ActiveTripScreen: React.FC<{ trip: Trip; onEndTrip: () => void; onUpdateStudent: (id: string, s: StudentStatus) => void; onReportIssue: () => void; showToast: (m: string, t?: ToastType) => void; gpsStatus: GpsStatus; onGpsClick: () => void; setActiveTrip: any; }> = ({ trip, onEndTrip, onUpdateStudent, onReportIssue, showToast, gpsStatus, onGpsClick, setActiveTrip }) => {
    const [view, setView] = useState<'boarding' | 'alighting'>(trip.type === 'Morning' ? 'boarding' : 'alighting');
    const [q, setQ] = useState('');
    const [isScan, setIsScan] = useState(false);
    const [selectedId, setSelectedId] = useState<Student | null>(null);

    const filtered = trip.students.filter(s => {
        const matchesQuery = s.name.toLowerCase().includes(q.toLowerCase());
        if (view === 'boarding') return matchesQuery && [StudentStatus.NotBoarded, StudentStatus.Absent].includes(s.status);
        return matchesQuery && [StudentStatus.Boarded, StudentStatus.Alighted].includes(s.status);
    });

    const handleAction = (s: Student, status: StudentStatus) => {
        if (status === StudentStatus.Boarded || status === StudentStatus.Alighted) {
            setIsScan(true);
            setTimeout(() => {
                setIsScan(false);
                onUpdateStudent(s.id, status);
                showToast(`${s.name} ${status.toLowerCase()}`, 'success');
            }, 1200);
        } else {
            onUpdateStudent(s.id, status);
        }
    };

    return (
        <div className="flex flex-col h-full bg-gray-50">
            <div className="bg-[#303690] p-5 pt-10 text-white rounded-b-3xl shadow-xl">
                <div className="flex justify-between items-center mb-4">
                    <div><h2 className="text-lg font-bold">{trip.type} Trip</h2><p className="text-xs opacity-60">{trip.route.name}</p></div>
                    <button onClick={onGpsClick} className={`text-[10px] font-bold px-3 py-1 rounded-full border border-white/20 flex items-center gap-1 ${gpsStatus === 'active' ? 'bg-green-500/20 text-green-300 border-green-500/30' : 'bg-white/10'}`}><Icon name="crosshair" className="w-3 h-3"/> {gpsStatus.toUpperCase()}</button>
                </div>
                <div className="space-y-2">
                    <div className="flex justify-between text-xs font-bold uppercase opacity-60"><span>Progress</span><span>{trip.students.filter(s => s.status === StudentStatus.Boarded).length} / {trip.students.length}</span></div>
                    <div className="h-2 bg-white/10 rounded-full overflow-hidden"><div className="h-full bg-[#E70D8D] transition-all duration-700" style={{width: `${(trip.students.filter(s => s.status === StudentStatus.Boarded).length / trip.students.length) * 100}%`}}></div></div>
                </div>
            </div>

            <div className="flex bg-white border-b border-gray-100">
                <button onClick={() => setView('boarding')} className={`flex-1 p-4 font-bold text-xs uppercase tracking-widest relative ${view === 'boarding' ? 'text-[#E70D8D]' : 'text-gray-400'}`}>Boarding {view === 'boarding' && <div className="absolute bottom-0 left-0 right-0 h-1 bg-[#E70D8D] rounded-t-full"></div>}</button>
                <button onClick={() => setView('alighting')} className={`flex-1 p-4 font-bold text-xs uppercase tracking-widest relative ${view === 'alighting' ? 'text-[#E70D8D]' : 'text-gray-400'}`}>Alighting {view === 'alighting' && <div className="absolute bottom-0 left-0 right-0 h-1 bg-[#E70D8D] rounded-t-full"></div>}</button>
            </div>

            <div className="p-4 bg-white border-b border-gray-50"><div className="relative"><Icon name="search" className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 w-4 h-4"/><input type="text" placeholder="Find student..." value={q} onChange={e => setQ(e.target.value)} className="w-full bg-gray-50 border border-gray-100 rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-[#303690]/10"/></div></div>

            <div className="flex-grow overflow-y-auto bg-white">
                {filtered.length > 0 ? (
                    <ul className="divide-y divide-gray-50">
                        {filtered.map(s => (
                            <li key={s.id} onClick={() => setSelectedId(s)} className="p-4 flex items-center gap-4 active:bg-gray-50 transition-colors">
                                <div className="relative"><img src={s.imgUrl} className="w-12 h-12 rounded-full border border-gray-100" alt="" />{s.status === StudentStatus.Boarded && <div className="absolute -bottom-1 -right-1 bg-green-500 rounded-full p-0.5 border-2 border-white"><Icon name="checkCircle" className="w-3 h-3 text-white"/></div>}</div>
                                <div className="flex-grow">
                                    <h4 className="font-bold text-[#303690] text-sm">{s.name}</h4>
                                    <p className="text-[10px] text-gray-400 uppercase font-bold">{s.admissionNumber} • {s.grade}</p>
                                    <div className="mt-1"><StatusBadge status={s.status}/></div>
                                </div>
                                <div className="flex gap-2">
                                    {view === 'boarding' && s.status === StudentStatus.NotBoarded && <button onClick={(e) => { e.stopPropagation(); handleAction(s, StudentStatus.Boarded); }} className="bg-[#303690] text-white text-[10px] font-bold px-4 py-2 rounded-xl uppercase">Board</button>}
                                    {view === 'alighting' && s.status === StudentStatus.Boarded && <button onClick={(e) => { e.stopPropagation(); handleAction(s, StudentStatus.Alighted); }} className="bg-[#E70D8D] text-white text-[10px] font-bold px-4 py-2 rounded-xl uppercase">Alight</button>}
                                </div>
                            </li>
                        ))}
                    </ul>
                ) : (
                    <div className="flex flex-col items-center justify-center h-64 text-gray-300 opacity-50"><Icon name="users" className="w-12 h-12 mb-2"/><p className="text-sm font-bold uppercase tracking-widest">No pending students</p></div>
                )}
            </div>

            <div className="p-4 bg-white border-t border-gray-100 flex gap-4 shadow-2xl">
                <button onClick={onReportIssue} className="bg-yellow-50 text-yellow-600 p-4 rounded-2xl border border-yellow-100"><Icon name="alertTriangle" className="w-6 h-6"/></button>
                <button onClick={onEndTrip} className="flex-grow bg-[#E70D8D] text-white font-bold p-4 rounded-2xl shadow-lg shadow-pink-200 active:scale-95 transition-transform flex items-center justify-center gap-2"><Icon name="logOut" className="w-5 h-5"/> End Trip</button>
            </div>

            {isScan && <div className="absolute inset-0 bg-[#303690]/90 z-[100] flex flex-col items-center justify-center text-white"><div className="w-24 h-24 bg-white/10 rounded-full animate-ping absolute"></div><Icon name="zap" className="w-16 h-16 text-[#E70D8D] relative z-10"/><p className="mt-8 text-xl font-bold tracking-widest">Scanning NFC...</p></div>}
            {selectedId && <StudentActionModal isOpen={!!selectedId} onClose={() => setSelectedId(null)} student={selectedId} onUpdateStatus={handleAction} mode="trip" onNotify={() => showToast('Notified guardian')} onCall={() => showToast('Calling guardian')} />}
        </div>
    );
};

