             <div className="absolute inset-0 opacity-30 bg-[url('https://www.transparenttextures.com/patterns/skulls.png')]"></div>
             <div className="absolute inset-0 grid grid-cols-6 grid-rows-4 gap-0.5 opacity-10 pointer-events-none">
                 {Array.from({length: 24}).map((_, i) => <div key={i} className="border border-gray-400"></div>)}
