                <Icon name="userCheck" className="w-12 h-12 text-[#303690]"/>
            </div>
            <h1 className="text-2xl font-bold text-[#303690] mb-2">Confirm Assignment</h1>
            <p className="text-gray-500 mb-8">Please confirm your details before starting.</p>

            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 w-full space-y-5 mb-8 text-left">
                <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">Driver</p>
                    <div className="flex items-center gap-3">
                        <div className="bg-blue-50 p-2 rounded-full">
                             <Icon name="user" className="w-4 h-4 text-[#303690]" />
                        </div>
                        <p className="text-lg font-semibold text-gray-800">{MOCK_DRIVER.name}</p>
                    </div>
                </div>
                 <div className="h-px bg-gray-100 w-full"></div>
                <div>
                    <p className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">Assigned Vehicle</p>
                     <div className="flex items-center gap-3">
                        <div className="bg-pink-50 p-2 rounded-full">
                             <Icon name="bus" className="w-4 h-4 text-[#E70D8D]" />
                        </div>
                         <p className="text-lg font-semibold text-gray-800">{MOCK_DRIVER.assignedZone}</p>
                    </div>
                </div>
            </div>

            <button 
                onClick={handleConfirm} 
                disabled={isConfirming}
                className="w-full bg-[#E70D8D] text-white font-bold py-4 rounded-xl shadow-lg hover:opacity-90 transition-colors h-14 flex items-center justify-center"
            >
                {isConfirming ? <Spinner className="text-white"/> : 'Confirm & Start'}
            </button>
             <div className="absolute bottom-4 text-gray-400 text-xs">
                 <button onClick={onVersionClick} className="hover:text-gray-600 transition-colors focus:outline-none">
                    Version {version}
