const HomeScreen: React.FC<{ navigate: (screen: Screen) => void; setHistoryType: (type: 'trip' | 'verification') => void; onVersionClick: () => void; }> = ({ navigate, setHistoryType, onVersionClick }) => {
    const greeting = useMemo(() => {
        const hour = new Date().getHours();
        if (hour < 12) return 'Good Morning';
        if (hour < 18) return 'Good Afternoon';
        return 'Good Evening';
    }, []);

    return (
        <div className="flex flex-col h-full bg-gray-50">
             <div className="bg-white p-6 shadow-sm border-b border-gray-100">
                <div className="flex justify-between items-center">
                    <div>
                        <h1 className="text-2xl font-bold text-[#303690]">{greeting},</h1>
                        <h1 className="text-2xl font-light text-gray-600 mb-1">{MOCK_DRIVER.name.split(' ')[0]}</h1>
                        <p className="text-sm text-gray-500 flex items-center gap-2 mt-2">
                           <span className="bg-blue-50 text-[#303690] px-2 py-0.5 rounded text-xs font-semibold">{MOCK_DRIVER.assignedZone}</span>
                           <span className="text-gray-300">|</span> 
                           <span>{MOCK_DRIVER.partnerName}</span>
                        </p>
                    </div>
