    <div className={`absolute inset-0 bg-[#303690] z-40 flex flex-col justify-center items-center text-white backdrop-blur-sm ${activeText ? 'bg-opacity-90' : 'bg-opacity-90'}`}>
        <div className="relative flex items-center justify-center">
            {!activeText && <div className="absolute w-32 h-32 bg-[#E70D8D] rounded-full animate-ping opacity-50"></div>}
            <div className="bg-white/10 p-8 rounded-full backdrop-blur-md">
                <Icon name={activeText ? 'zap' : 'smartphone'} className="w-16 h-16 text-pink-400" />
            </div>
        </div>
        <p className="mt-8 text-xl font-bold tracking-wider text-white">{activeText || 'Ready to Scan...'}</p>
        <p className="text-blue-300 mt-2">Hold card near back of device</p>
    </div>
);

