                 <h3 className="text-2xl font-bold text-gray-900 mb-1">{student.name}</h3>
                 <p className="text-gray-500 font-medium text-sm mb-6">{student.grade} • {student.admissionNumber}</p>

                 {student.alert && (
                     <div className="w-full bg-pink-50 rounded-2xl p-4 mb-8 border border-pink-100 relative overflow-hidden">
                        <div className="absolute top-0 left-0 w-1 h-full bg-[#E70D8D]"></div>
                        <div className="flex flex-col items-center relative z-10">
                            <p className="text-[#E70D8D] font-bold text-xs uppercase tracking-widest mb-1">Alert</p>
                            <p className="text-gray-800 text-center font-semibold">{student.alert}</p>
                        </div>
                     </div>
                 )}

                 {!student.alert && (
                     <p className="text-gray-600 text-center mb-8 px-4">
                        Please confirm the action for this student.
                     </p>
                 )}

                 <div className="grid grid-cols-2 gap-4 w-full">
                    <button onClick={onClose} className="py-4 rounded-2xl bg-gray-50 text-gray-600 font-bold hover:bg-gray-100 transition-colors text-sm uppercase tracking-wide">
                        Cancel
                    </button>
                    <button onClick={() => onConfirm(student)} className="py-4 rounded-2xl bg-[#E70D8D] text-white font-bold shadow-lg shadow-pink-200 hover:shadow-xl hover:opacity-95 transition-all transform active:scale-[0.98] text-sm uppercase tracking-wide">
                        {confirmText}
