        className={`bg-white rounded-2xl shadow-sm border border-gray-100 p-5 flex flex-col items-center justify-center ${onClick ? 'cursor-pointer hover:bg-pink-50 hover:border-pink-200 transition-all active:scale-95' : ''}`}
