             <Icon name={icon} className="w-5 h-5 text-[#E70D8D]"/>
        </div>
        <p className="text-gray-500 text-xs font-bold uppercase tracking-wide mb-1">{label}</p>
        <p className="font-bold text-2xl text-gray-800">{value}</p>
