                <div>
                    <h3 className="text-sm font-bold uppercase text-gray-500 mb-3 tracking-wider">Issues Reported ({trip.issues.length})</h3>
                    {trip.issues.length > 0 ? (
                        <ul className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 space-y-3">{trip.issues.map((issue, index) => (<li key={index} className="border-b border-gray-100 last:border-b-0 pb-2 last:pb-0"><p className="font-semibold text-gray-800">{issue.type}</p><p className="text-sm text-gray-600">{issue.note}</p></li>))}</ul>
                    ) : (
                        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 text-center text-gray-400">No issues reported.</div>
