            <div className="p-4 bg-white border-t border-gray-100 space-y-3">
                 <button onClick={onBack} className="w-full bg-gray-100 text-gray-600 font-bold py-4 rounded-xl">Go Back</button>
                 <button onClick={handleSubmit} disabled={isSubmitting} className="w-full bg-[#E70D8D] text-white font-bold py-4 rounded-xl shadow-lg hover:opacity-90 transition-colors h-14 flex items-center justify-center">
                    {isSubmitting ? <Spinner className="text-white"/> : 'Submit Report'}
                 </button>
            </div>
