    const [issueType, setIssueType] = useState<IssueType>(IssueType.Traffic);
    const [note, setNote] = useState('');
    const [isReporting, setIsReporting] = useState(false);

    const handleSubmit = () => { 
        setIsReporting(true);
        setTimeout(() => {
            onReport({ type: issueType, note, timestamp: new Date() }); 
            setNote('');
