// Main App Component
const App: React.FC = () => {
    const [screen, setScreen] = useState<Screen>(Screen.Login);
    const [isLoadingScreen, setIsLoadingScreen] = useState(false);
    const [isDeviceRegistered, setIsDeviceRegistered] = useState(false);
    const [activeTrip, setActiveTrip] = useState<Trip | null>(null);
    const [selectedTripType, setSelectedTripType] = useState<TripType | null>(null);
    const [toast, setToast] = useState<{ message: string; type: ToastType } | null>(null);
    const [modal, setModal] = useState<'delay' | 'otp' | 'version' | 'logout' | 'dateRange' | 'verificationDetails' | 'dataHistory' | 'map' | 'registerDevice' | 'otaUpdate' | null>(null);
    const [historyType, setHistoryType] = useState<'trip' | 'verification'>('trip');
    const [selectedTripReport, setSelectedTripReport] = useState<TripHistoryItem | null>(null);
    const [selectedVerification, setSelectedVerification] = useState<VerificationHistoryItem | null>(null);
    const [customDateRange, setCustomDateRange] = useState<{ start: Date | null, end: Date | null }>({ start: null, end: null });
    const [gpsStatus, setGpsStatus] = useState<GpsStatus>('inactive');
    const [currentLocation, setCurrentLocation] = useState<Coordinates | null>(null);
    const [dataUsage, setDataUsage] = useState(12.4); // Simulated data usage in MB
    const [dataUsageHistory, setDataUsageHistory] = useState(MOCK_DATA_USAGE_HISTORY);
    const [otaStatus, setOtaStatus] = useState<'available' | 'downloading' | 'installing' | 'up-to-date'>('available');
    const [settings, setSettings] = useState({
        notifications: true,
        offlineMode: false,
    });
    const [isOnline, setIsOnline] = useState(navigator.onLine);
    const [batteryStatus, setBatteryStatus] = useState<{ level: number, charging: boolean } | null>(null);

    // Check for device registration on load
    useEffect(() => {
        if (!isDeviceRegistered && screen === Screen.Login) {
            const timer = setTimeout(() => {
                setModal('registerDevice');
            }, 1500);
            return () => clearTimeout(timer);
        }
    }, [isDeviceRegistered, screen]);

    // Simulating GPS tracking
    useEffect(() => {
        let watchId: number;
        if (screen === Screen.ActiveTrip) {
            setGpsStatus('active');
            watchId = navigator.geolocation.watchPosition(
                (position) => {
                    setCurrentLocation({ lat: position.coords.latitude, lon: position.coords.longitude });
                    if (gpsStatus !== 'active') setGpsStatus('active');
                },
                (error) => {
                    console.error('Geolocation error:', error);
                    setGpsStatus('error');
                },
                { enableHighAccuracy: true }
            );
        }
        return () => {
            if (watchId) {
                navigator.geolocation.clearWatch(watchId);
                setGpsStatus('inactive');
                setCurrentLocation(null);
            }
        };
    }, [screen, gpsStatus]);

    // Simulate data usage accumulation
    useEffect(() => {
        const interval = setInterval(() => {
            setDataUsage(prev => +(prev + 0.01).toFixed(2));
        }, 5000);
        return () => clearInterval(interval);
    }, []);

    const showToast = (message: string, type: ToastType = 'success') => {
        setToast({ message, type });
    };

    // Effect for internet connectivity
    useEffect(() => {
        const handleOnline = () => {
            setIsOnline(true);
            showToast('Internet connection restored.', 'success');
        };
        const handleOffline = () => {
            setIsOnline(false);
            showToast('Internet connection lost.', 'error');
        };

        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);

        return () => {
            window.removeEventListener('online', handleOnline);
            window.removeEventListener('offline', handleOffline);
        };
    }, []);

    // Effect for battery status
    useEffect(() => {
        let batteryManager: any = null;

        const updateBatteryStatus = () => {
            if (batteryManager) {
                setBatteryStatus({
                    level: batteryManager.level,
                    charging: batteryManager.charging
                });
            }
        };

        if ('getBattery' in navigator) {
            (navigator as any).getBattery().then((bm: any) => {
                batteryManager = bm;
                updateBatteryStatus();

                batteryManager.addEventListener('levelchange', updateBatteryStatus);
                batteryManager.addEventListener('chargingchange', updateBatteryStatus);
            });
        }

        return () => {
            if (batteryManager) {
                batteryManager.removeEventListener('levelchange', updateBatteryStatus);
                batteryManager.removeEventListener('chargingchange', updateBatteryStatus);
            }
        };
    }, []);

    const handleSettingChange = (key: keyof typeof settings, value: any) => {
        setSettings(prev => ({...prev, [key]: value }));
        showToast(`${String(key).charAt(0).toUpperCase() + String(key).slice(1)} updated.`, 'info');
    };

    const handleResetDataUsage = () => {
        setDataUsage(0);
        setDataUsageHistory([]);
        showToast('Data usage history has been reset.', 'info');
    };

    const navigate = (newScreen: Screen) => {
        const screensWithLoaders = [Screen.Home, Screen.ActiveTrip, Screen.GateAttendance, Screen.Profile, Screen.History, Screen.TripReport, Screen.Settings, Screen.TripSelection, Screen.RouteSelection];
        if (screensWithLoaders.includes(newScreen)) {
            setIsLoadingScreen(true);
            setTimeout(() => {
                setScreen(newScreen);
                setIsLoadingScreen(false);
            }, 1000); // Simulate loading
        } else {
            setScreen(newScreen);
        }
    };

    const handleLogin = (success: boolean) => {
        if (!isDeviceRegistered) {
            setModal('registerDevice');
            return;
        }
        if (success) navigate(Screen.DriverConfirmation);
    };

    const handleTripTypeSelection = (type: TripType) => {
        setSelectedTripType(type);
        navigate(Screen.RouteSelection);
    };

    const startTrip = (route: Route) => {
        if (!selectedTripType) return;
        const students = MOCK_STUDENTS.map(s => ({...s, status: StudentStatus.NotBoarded}));
        setActiveTrip({
            type: selectedTripType,
            route: route,
            startTime: new Date(),
            students,
            issues: [],
        });
        navigate(Screen.ActiveTrip);
    };

    const updateStudentStatus = (studentId: string, newStatus: StudentStatus) => {
        if (activeTrip) {
            setActiveTrip(prev => {
                if (!prev) return null;
                return {
                    ...prev,
                    students: prev.students.map(s => s.id === studentId ? { ...s, status: newStatus, lastUpdateTime: new Date() } : s),
                };
            });
        }
    };

    const endTrip = () => {
        setActiveTrip(prev => prev ? { ...prev, endTime: new Date() } : null);
        navigate(Screen.TripSummary);
    };

    const reportIssue = (issue: Issue) => {
        setActiveTrip(prev => prev ? { ...prev, issues: [...prev.issues, issue] } : null);
        setModal(null);
        showToast(`Issue reported: ${issue.type}`);
    };

    const renderScreen = () => {
        if (isLoadingScreen) {
           switch (screen) {
                case Screen.Home: return <HomeScreenSkeleton />;
                case Screen.ActiveTrip:
                case Screen.GateAttendance: return <StudentListSkeleton />;
                case Screen.Profile: return <ProfileScreenSkeleton />;
                case Screen.History: return <HistoryScreenSkeleton />;
                case Screen.TripSummary:
                case Screen.TripReport: return <TripSummarySkeleton />;
                case Screen.Settings: return <SettingsScreenSkeleton />;
                case Screen.RouteSelection: return <HistoryScreenSkeleton />;
                default: return <div className="h-full w-full flex items-center justify-center"><Spinner className="w-10 h-10 text-[#303690]"/></div>;
            }
        }

        switch (screen) {
            case Screen.Login: return <LoginScreen onLogin={handleLogin} version={APP_VERSION} onVersionClick={() => setModal('version')} />;
            case Screen.DriverConfirmation: return <DriverConfirmationScreen onConfirm={() => navigate(Screen.Home)} version={APP_VERSION} onVersionClick={() => setModal('version')} />;
            case Screen.Home: return <HomeScreen navigate={navigate} setHistoryType={setHistoryType} onVersionClick={() => setModal('version')} />;
            case Screen.TripSelection: return <TripSelectionScreen onSelectTripType={handleTripTypeSelection} onBack={() => navigate(Screen.Home)} showToast={showToast} />;
            case Screen.RouteSelection: return <RouteSelectionScreen onSelectRoute={startTrip} onBack={() => navigate(Screen.TripSelection)} />;
            case Screen.ActiveTrip: 
                return activeTrip && <ActiveTripScreen 
                    trip={activeTrip} 
                    onEndTrip={endTrip} 
                    onUpdateStudent={updateStudentStatus} 
                    onReportIssue={() => setModal('delay')} 
                    showToast={showToast}
                    gpsStatus={gpsStatus}
                    onGpsClick={() => setModal('map')}
                    setActiveTrip={setActiveTrip}
                />;
            case Screen.TripSummary:
                return activeTrip && <TripSummaryScreen trip={activeTrip} onDone={() => { setActiveTrip(null); navigate(Screen.Home);}} onBack={() => navigate(Screen.ActiveTrip)} />;
            case Screen.GateAttendance:
                return <GateAttendanceScreen onBack={() => navigate(Screen.Home)} onGuardianVerify={() => setModal('otp')} showToast={showToast}/>;
            case Screen.Profile:
                return <ProfileScreen onBack={() => navigate(Screen.Home)} onLogoutClick={() => setModal('logout')} onSettingsClick={() => navigate(Screen.Settings)} />;
            case Screen.Settings:
                 return <SettingsScreen 
                    onBack={() => navigate(Screen.Profile)}
                    settings={settings}
                    onSettingChange={handleSettingChange}
                    dataUsage={dataUsage}
                    onOpenDataHistory={() => setModal('dataHistory')}
                    otaStatus={otaStatus}
                    onOpenOTA={() => setModal('otaUpdate')}
                />;
            case Screen.History:
                return <HistoryScreen 
                    onBack={() => navigate(Screen.Home)} 
                    initialTab={historyType} 
                    onSelectTrip={(trip) => {
                        setSelectedTripReport(trip);
                        navigate(Screen.TripReport);
                    }}
                    onSelectVerification={(verification) => {
                        setSelectedVerification(verification);
                        setModal('verificationDetails');
                    }}
                    customDateRange={customDateRange}
                    onOpenDateRangePicker={() => setModal('dateRange')}
                    setCustomDateRange={setCustomDateRange}
                />;
            case Screen.TripReport:
                return selectedTripReport && <TripReportScreen trip={selectedTripReport} onClose={() => navigate(Screen.History)} />;
            default: return <LoginScreen onLogin={handleLogin} version={APP_VERSION} onVersionClick={() => setModal('version')} />;
        }
    };

    const showLowBatteryWarning = batteryStatus && batteryStatus.level <= 0.20 && !batteryStatus.charging;

    return (
        <div className="h-full w-full bg-gray-50 font-sans flex flex-col relative pt-8 text-gray-800">
            {!isOnline && (
                <SystemStatusBanner 
                    message="No Internet Connection" 
                    icon="wifiOff" 
                    className="bg-red-600"
                />
            )}
            {showLowBatteryWarning && (
                <SystemStatusBanner
                    message={`Low Battery: ${(batteryStatus.level * 100).toFixed(0)}% remaining`}
                    icon="alertTriangle"
                    className="bg-yellow-500"
                />
            )}
            {renderScreen()}
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

            <DeviceRegistrationModal 
                isOpen={modal === 'registerDevice'} 
                onClose={() => setModal(null)} 
                onRegister={() => {
                    setIsDeviceRegistered(true);
                    setModal(null);
                    showToast('Device successfully registered on Terra GO.');
                }}
            />
            <DelayReportModal isOpen={modal === 'delay'} onClose={() => setModal(null)} onReport={reportIssue} />
            <GuardianOtpModal 
                isOpen={modal === 'otp'} 
                onClose={() => setModal(null)} 
                onSuccess={(guardianName, studentName) => {
                    showToast(`Verified: ${studentName} released to ${guardianName}.`);
                }}
            />
            <VersionInfoModal isOpen={modal === 'version'} onClose={() => setModal(null)} />
            <LogoutConfirmationModal 
                isOpen={modal === 'logout'}
                onClose={() => setModal(null)}
                onConfirm={() => {
                    setModal(null);
                    setActiveTrip(null);
                    setScreen(Screen.Login); 
                }}
            />
             <DateRangePickerModal
                isOpen={modal === 'dateRange'}
                onClose={() => setModal(null)}
                onApply={(start, end) => {
                    setCustomDateRange({ start, end });
                    setModal(null);
                }}
                initialRange={customDateRange}
            />
            <VerificationDetailsModal
                isOpen={modal === 'verificationDetails'}
                onClose={() => setModal(null)}
                verification={selectedVerification}
            />
            <DataUsageHistoryModal
                isOpen={modal === 'dataHistory'}
                onClose={() => setModal(null)}
                history={dataUsageHistory}
                onReset={handleResetDataUsage}
            />
            <MapModal 
                isOpen={modal === 'map'}
                onClose={() => setModal(null)}
                location={currentLocation}
            />
            <OTAUpdateModal 
                isOpen={modal === 'otaUpdate'} 
                onClose={() => setModal(null)} 
                onSuccess={() => {
                    setOtaStatus('up-to-date');
                    setModal(null);
                    showToast('App updated successfully!', 'success');
                }}
            />
        </div>
    );
};

const Header: React.FC<{ title: string; onBack?: () => void; showProfile?: boolean; navigate?: (screen: Screen) => void; pinkAccent?: boolean; }> = ({ title, onBack, showProfile, navigate, pinkAccent }) => (
    <div className={`p-4 shadow-sm flex items-center justify-between sticky top-0 z-10 border-b ${pinkAccent ? 'bg-white border-pink-100' : 'bg-white border-gray-100'}`}>
        {onBack ? <button onClick={onBack} className={`font-medium flex items-center gap-1 transition-colors ${pinkAccent ? 'text-[#E70D8D]' : 'text-[#303690] hover:text-[#E70D8D]'}`}>&larr; Back</button> : <div className="w-12"/>}
        <h1 className={`text-lg font-bold text-center tracking-tight ${pinkAccent ? 'text-[#E70D8D]' : 'text-[#303690]'}`}>{title}</h1>
        {showProfile && navigate ? 
            <button onClick={() => navigate(Screen.Profile)} className="text-gray-500 hover:text-[#E70D8D] transition-colors"><Icon name="user"/></button> : <div className='w-6'/>
        }
    </div>
);

const LoginScreen: React.FC<{ onLogin: (success: boolean) => void; version: string; onVersionClick: () => void; }> = ({ onLogin, version, onVersionClick }) => {
    const [email, setEmail] = useState('driver@terra.go');
    const [password, setPassword] = useState('password123');
    const [error, setError] = useState('');
    const [view, setView] = useState<'login' | 'forgot' | 'forgot_confirmation'>('login');
    const [forgotEmail, setForgotEmail] = useState('');
    const [isLoggingIn, setIsLoggingIn] = useState(false);
    const [isSendingLink, setIsSendingLink] = useState(false);

    const handleLoginClick = () => {
        setError('');
        setIsLoggingIn(true);
        setTimeout(() => {
            if (email.toLowerCase() === 'driver@terra.go' && password === 'password123') {
                onLogin(true);
            } else {
                setError('Invalid email or password.');
                onLogin(false);
            }
            setIsLoggingIn(false);
        }, 1500);
    };

    const handleForgotPassword = () => {
        if (forgotEmail && forgotEmail.includes('@')) {
            setIsSendingLink(true);
            setTimeout(() => {
                setView('forgot_confirmation');
                setIsSendingLink(false);
            }, 1500);
        }
    };

    const renderLoginView = () => (
        <>
            <input className="w-full p-4 rounded-xl mb-4 text-gray-800 bg-gray-50 border border-gray-200 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#E70D8D]" type="email" placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} />
            <input className="w-full p-4 rounded-xl mb-6 text-gray-800 bg-gray-50 border border-gray-200 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#E70D8D]" type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)} />
            {error && <p className="text-pink-600 text-center mb-4 font-medium bg-pink-50 py-2 rounded-lg border border-pink-100">{error}</p>}
            <button 
                className="w-full bg-[#E70D8D] text-white font-bold p-4 rounded-xl shadow-lg hover:opacity-90 transition-colors flex justify-center items-center h-14" 
                onClick={handleLoginClick}
                disabled={isLoggingIn}
            >
                {isLoggingIn ? <Spinner className="text-white"/> : 'Login'}
            </button>
            <button onClick={() => setView('forgot')} className="w-full text-center mt-6 text-[#303690] text-sm hover:underline transition-colors">Forgot Password?</button>
        </>
    );

    const renderForgotView = () => (
        <>
            <h2 className="text-2xl font-bold mb-2 text-center text-[#303690]">Reset Password</h2>
            <p className="text-gray-500 mb-8 text-center">Enter your email to receive a reset link.</p>
            <input className="w-full p-4 rounded-xl mb-4 bg-gray-50 border border-gray-200 text-gray-800 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-[#E70D8D]" type="email" placeholder="Your Email Address" value={forgotEmail} onChange={e => setForgotEmail(e.target.value)} />
            <button 
                className="w-full bg-[#E70D8D] text-white font-bold p-4 rounded-xl shadow-lg hover:opacity-90 transition-colors flex justify-center items-center h-14" 
                onClick={handleForgotPassword}
                disabled={isSendingLink}
            >
                {isSendingLink ? <Spinner className="text-white" /> : 'Send Reset Link'}
            </button>
            <button onClick={() => setView('login')} className="w-full text-center mt-6 text-[#303690] text-sm hover:underline transition-colors">Back to Login</button>
        </>
    );

    const renderConfirmationView = () => (
        <>
            <div className="bg-blue-50 p-6 rounded-full mb-6 mx-auto w-fit">
                <Icon name="send" className="w-12 h-12 text-[#E70D8D]"/>
            </div>
            <h2 className="text-2xl font-bold mb-2 text-center text-[#303690]">Check Your Email</h2>
            <p className="text-gray-500 mb-8 text-center">A password reset link has been sent to <strong className="text-[#303690]">{forgotEmail}</strong> if an account exists.</p>
            <button onClick={() => { setView('login'); setForgotEmail(''); }} className="w-full bg-[#303690] text-white font-bold p-4 rounded-xl shadow-lg hover:opacity-90 transition-colors">Back to Login</button>
        </>
    );

    return (
        <div className="flex flex-col h-full bg-white p-8 relative overflow-hidden">
            <div className="absolute -top-20 -right-20 w-64 h-64 bg-blue-50 rounded-full blur-3xl opacity-60"></div>
            <div className="absolute top-40 -left-20 w-48 h-48 bg-pink-50 rounded-full blur-3xl opacity-60"></div>

            <div className="flex-grow flex flex-col items-center justify-center relative z-10">
                {view === 'login' && (
                    <>
                        <img src="https://lionnomb.sirv.com/Terra%20Go/Artboard%204%20copy.png" alt="Terra Go Logo" className="w-28 h-28 object-contain mb-6 drop-shadow-lg" />
                        <h1 className="text-3xl font-bold mb-1 tracking-tight text-[#303690]">Terra Go</h1>
                        <p className="text-lg text-gray-500 mb-12 font-medium">Driver Companion</p>
                    </>
                )}

                <div className="w-full">
                    {view === 'login' && renderLoginView()}
                    {view === 'forgot' && renderForgotView()}
                    {view === 'forgot_confirmation' && renderConfirmationView()}
                </div>
            </div>
             <div className="py-2 text-center text-gray-400 text-xs relative z-10">
                 <button onClick={onVersionClick} className="hover:text-gray-600 transition-colors focus:outline-none">
                    Version {version}
                </button>
            </div>
        </div>
    );
};

