const OTAUpdateModal: React.FC<{ isOpen: boolean; onClose: () => void; onSuccess: () => void; }> = ({ isOpen, onClose, onSuccess }) => {
    const [step, setStep] = useState<'notice' | 'downloading' | 'complete'>('notice');
    const [progress, setProgress] = useState(0);

    const startUpdate = () => {
        setStep('downloading');
        const interval = setInterval(() => {
            setProgress(prev => {
                if (prev >= 100) {
                    clearInterval(interval);
                    setStep('complete');
                    return 100;
                }
                return prev + 2;
            });
        }, 50);
    };

    if (!isOpen) return null;

    return (
        <Modal isOpen={isOpen} onClose={step === 'downloading' ? () => {} : onClose} title="Software Update">
            <div className="flex flex-col items-center gap-6 py-2">
                {step === 'notice' && (
                    <>
                        <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center">
                            <Icon name="wifi" className="w-10 h-10 text-[#303690]" />
                        </div>
                        <div className="text-center">
                            <h3 className="text-xl font-bold text-[#303690]">New Update Available</h3>
