const TripSelectionScreen: React.FC<{ onSelectTripType: (type: TripType) => void; onBack: () => void; showToast: (msg: string) => void }> = ({ onSelectTripType, onBack, showToast }) => {
    const [isLoading, setIsLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'regular' | 'one-off'>('regular');
    const [currentTime, setCurrentTime] = useState(new Date());

    useEffect(() => {
        setIsLoading(true);
        const timer = setTimeout(() => setIsLoading(false), 1000);
        return () => clearTimeout(timer);
    }, [activeTab]);

    useEffect(() => {
        const interval = setInterval(() => setCurrentTime(new Date()), 60000);
        return () => clearInterval(interval);
    }, []);

    const getRelativeDayString = (dateStr: string) => {
        const today = new Date();
        today.setHours(0, 0, 0, 0);

        const tomorrow = new Date(today);
        tomorrow.setDate(tomorrow.getDate() + 1);

        const target = new Date(dateStr + 'T00:00:00');

        if (target.getTime() === today.getTime()) return 'Today';
        if (target.getTime() === tomorrow.getTime()) return 'Tomorrow';

        return target.toLocaleDateString('en-US', { weekday: 'long' });
    };

    // Identification of the trip closest to now
    const filteredTrips = useMemo(() => MOCK_SCHEDULED_TRIPS.filter(t => t.category === activeTab), [activeTab]);

    const closestTripId = useMemo(() => {
        if (filteredTrips.length === 0) return null;

        let minDiff = Infinity;
        let closestId = null;

        filteredTrips.forEach(trip => {
            const scheduled = new Date(`${trip.scheduledDate}T${trip.scheduledTime}:00`);
            const diff = Math.abs(currentTime.getTime() - scheduled.getTime());
            if (diff < minDiff) {
                minDiff = diff;
                closestId = trip.id;
            }
        });

        return closestId;
    }, [filteredTrips, currentTime]);

    return (
        <div className="flex flex-col h-full bg-gray-50">
            <Header title="Available Trips" onBack={onBack}/>

            <div className="px-4 py-4 bg-white border-b border-gray-100">
                <div className="flex bg-gray-100 rounded-xl p-1">
                    <button 
                        onClick={() => setActiveTab('regular')}
                        className={`flex-1 py-2.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'regular' ? 'bg-white text-[#E70D8D] shadow-sm' : 'text-gray-500'}`}
                    >
                        Schedule
                    </button>
                    <button 
                        onClick={() => setActiveTab('one-off')}
                        className={`flex-1 py-2.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'one-off' ? 'bg-white text-[#E70D8D] shadow-sm' : 'text-gray-500'}`}
                    >
                        One-Offs
                    </button>
                </div>
            </div>

            <div className="flex-grow p-4 overflow-y-auto space-y-4">
                {isLoading ? (
                    <>
                        <Skeleton className="w-full h-24 rounded-2xl" />
                        <Skeleton className="w-full h-24 rounded-2xl" />
                        <Skeleton className="w-full h-24 rounded-2xl" />
                    </>
                ) : (
                    <>
                        {filteredTrips.map((trip) => {
                            const active = trip.id === closestTripId;
                            const dayLabel = getRelativeDayString(trip.scheduledDate);
                            return (
                                <ScheduledTripCard 
                                    key={trip.id}
                                    trip={trip}
                                    isActive={active}
                                    statusText={`${dayLabel} @ ${trip.scheduledTime}`}
                                    onClick={() => {
                                        if (active) onSelectTripType(trip.type);
                                        else showToast(`This trip is not the closest to the current time. Demo allows starting the closest trip.`);
                                    }}
                                />
                            );
                        })}

                        {activeTab === 'one-off' && (
                            <button 
                                onClick={() => onSelectTripType('Custom')}
                                className="w-full border-2 border-dashed border-gray-200 rounded-2xl p-6 flex flex-col items-center justify-center gap-2 group hover:border-[#E70D8D]/30 transition-colors"
                            >
                                <div className="p-3 bg-gray-50 rounded-full group-hover:bg-pink-50 transition-colors">
                                    <Icon name="plus" className="w-6 h-6 text-gray-400 group-hover:text-[#E70D8D]" />
                                </div>
                                <span className="text-sm font-bold text-gray-500 group-hover:text-[#E70D8D]">Start Custom One-Off</span>
                            </button>
                        )}
                    </>
                )}
            </div>

            <div className="p-4 text-center">
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">
                    Current Time: {currentTime.toLocaleDateString([], { weekday: 'short', month: 'short', day: 'numeric' })} &bull; {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </p>
            </div>
        </div>
    );
};

