                    <img src={student.imgUrl} alt={student.name} className="w-24 h-24 rounded-full border-4 border-white shadow-xl relative z-10 object-cover" />
                    {student.alert && (
                        <div className="absolute -bottom-2 -right-2 bg-[#E70D8D] rounded-full p-2.5 border-4 border-white z-20 shadow-sm">
