    <div className="flex flex-col h-full bg-gray-50 absolute inset-0 z-20">
         <div className="bg-[#E70D8D] text-white p-6 shadow-md relative">
            <button onClick={onClose} className="absolute top-6 left-4 p-2 bg-white/20 rounded-full hover:bg-white/30 transition-colors">
                <Icon name="arrowRight" className="w-5 h-5 text-white rotate-180" />
            </button>
            <div className="text-center mt-4">
                <h2 className="text-2xl font-bold">{trip.type} Trip Report</h2>
                <p className="opacity-80 text-sm">{trip.startTime.toLocaleDateString()} • {trip.route.name}</p>
            </div>
        </div>
        <div className="flex-grow overflow-y-auto p-6 space-y-6">
            <div className="grid grid-cols-2 gap-4">
                <SummaryCard icon="users" label="Total Students" value={`${trip.students.length}`} />
                <SummaryCard icon="alertTriangle" label="Issues" value={`${trip.issues.length}`} />
            </div>

            <div>
                <h3 className="text-sm font-bold uppercase text-gray-500 mb-3 tracking-wider">Details</h3>
                 <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 space-y-4">
                    <div className="flex justify-between items-center border-b border-gray-50 pb-3">
                        <span className="text-gray-600">Start Time</span>
                        <span className="font-bold text-gray-800">{trip.startTime.toLocaleTimeString()}</span>
                    </div>
                     <div className="flex justify-between items-center border-b border-gray-50 pb-3">
                        <span className="text-gray-600">End Time</span>
                        <span className="font-bold text-gray-800">{trip.endTime?.toLocaleTimeString() || 'N/A'}</span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-gray-600">Absent Students</span>
                        <span className="font-bold text-red-500">{trip.students.filter(s => s.status === StudentStatus.Absent).length}</span>
                    </div>
                 </div>
            </div>

             {trip.issues.length > 0 && (
                <div>
                    <h3 className="text-sm font-bold uppercase text-gray-500 mb-3 tracking-wider">Reported Issues</h3>
                    <ul className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4 space-y-3">
                        {trip.issues.map((issue, idx) => (
                             <li key={idx} className="flex gap-3 items-start">
                                <Icon name="alertTriangle" className="w-5 h-5 text-yellow-500 flex-shrink-0 mt-0.5"/>
                                <div>
                                    <p className="font-bold text-gray-800 text-sm">{issue.type}</p>
                                    <p className="text-sm text-gray-600 leading-snug">{issue.note}</p>
                                    <p className="text-xs text-gray-400 mt-1">{issue.timestamp.toLocaleTimeString()}</p>
                                </div>
                            </li>
                        ))}
                    </ul>
                </div>
            )}
        </div>
    </div>
);

